CREATE DATABASE IF NOT EXISTS dbu_reservations CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dbu_reservations;
CREATE TABLE IF NOT EXISTS departments(department_id BIGINT PRIMARY KEY AUTO_INCREMENT,department_name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users(user_id BIGINT PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(160) NOT NULL,university_id VARCHAR(60) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40),department_id BIGINT NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','LECTURER','STUDENT') NOT NULL DEFAULT 'STUDENT',account_status ENUM('PENDING','ACTIVE','DISABLED') NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(department_id));
CREATE TABLE IF NOT EXISTS rooms(room_id BIGINT PRIMARY KEY AUTO_INCREMENT,room_name VARCHAR(120) NOT NULL,room_type ENUM('CLASSROOM','LABORATORY') NOT NULL,building VARCHAR(120) NOT NULL,floor INT NOT NULL DEFAULT 0,capacity INT NOT NULL,equipment TEXT,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',UNIQUE KEY uq_room_name_building(room_name,building),CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS reservations(reservation_id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,room_id BIGINT NOT NULL,reservation_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,participant_count INT NOT NULL,purpose VARCHAR(250) NOT NULL,description TEXT,status ENUM('PENDING','APPROVED','REJECTED','CANCELLED') NOT NULL DEFAULT 'PENDING',rejection_reason VARCHAR(500),processed_by BIGINT,processed_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(room_id) REFERENCES rooms(room_id),FOREIGN KEY(processed_by) REFERENCES users(user_id),CHECK(participant_count>0),CHECK(start_time<end_time),INDEX ix_room_slot(room_id,reservation_date,status,start_time,end_time),INDEX ix_user_reservations(user_id,created_at));
CREATE TABLE IF NOT EXISTS notifications(notification_id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,message VARCHAR(500) NOT NULL,notification_status ENUM('UNREAD','READ') NOT NULL DEFAULT 'UNREAD',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),INDEX ix_notifications_user(user_id,notification_status));
